describe('Pagination Controls - Load Correct Page of Results', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should load the correct page of results when navigating pagination controls', () => {
    // Verify initial page loads correctly
    cy.get('[data-testid="pagination-controls"]').should('be.visible');
    cy.get('[data-testid="page-1-button"]').should('be.visible');
    cy.get('[data-testid="page-2-button"]').should('be.visible');
    cy.get('[data-testid="page-3-button"]').should('be.visible');
    cy.get('[data-testid="page-1-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify page 2 loads correctly
    cy.get('[data-testid="page-2-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify page 3 loads correctly
    cy.get('[data-testid="page-3-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify navigation back to page 1 works
    cy.get('[data-testid="page-1-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify navigation to page 2 from page 1 works
    cy.get('[data-testid="page-2-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify navigation to page 3 from page 2 works
    cy.get('[data-testid="page-3-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify navigation to page 1 from page 3 works
    cy.get('[data-testid="page-1-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
  });

  it('should handle edge case when navigating to a non-existent page', () => {
    // Verify initial page loads correctly
    cy.get('[data-testid="pagination-controls"]').should('be.visible');
    cy.get('[data-testid="page-1-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify navigation to a non-existent page (e.g., page 10)
    cy.get('[data-testid="page-10-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Page does not exist');

    // Verify pagination controls are still visible
    cy.get('[data-testid="pagination-controls"]').should('be.visible');

    // Verify user can navigate back to valid pages
    cy.get('[data-testid="page-1-button"]').click();
    cy.get('[data-testid="results-container"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);
  });
});
